import boto3
from botocore.exceptions import ClientError
from pathlib import Path

_s3 = boto3.client(
    's3',
    aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
    aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY'),
    region_name=os.getenv('AWS_REGION'),
)
BUCKET = os.getenv('S3_BUCKET_NAME')

def upload_file(local_path: str | Path, s3_key: str, content_type: str = 'application/octet-stream') -> bool:
    try:
        _s3.upload_file(str(local_path), BUCKET, s3_key, ExtraArgs={'ContentType': content_type})
        return True
    except ClientError as e:
        return False

def upload_bytes(data: bytes, s3_key: str, content_type: str = 'application/octet-stream') -> bool:
    try:
        _s3.put_object(Bucket=BUCKET, Key=s3_key, Body=data, ContentType=content_type)
        return True
    except ClientError:
        return False

def download_file(s3_key: str, local_path: str | Path) -> bool:
    try:
        _s3.download_file(BUCKET, s3_key, str(local_path))
        return True
    except ClientError:
        return False

def delete_file(s3_key: str) -> bool:
    try:
        _s3.delete_object(Bucket=BUCKET, Key=s3_key)
        return True
    except ClientError:
        return False

def get_presigned_url(s3_key: str, expires_in: int = 3600) -> str:
    return _s3.generate_presigned_url('get_object', Params={'Bucket': BUCKET, 'Key': s3_key}, ExpiresIn=expires_in)

